-- =============================================================================
-- FillMate - core schema (PostgreSQL / Supabase)
--
-- Generated from lib/db/schema.ts by npm run gen:migrations.
-- Do not edit by hand: edit the schema definition and regenerate.
--
-- Conventions
--   * ids are UUIDs generated by the application (gen_random_uuid() as default)
--   * every timestamp is timestamptz and stored in UTC
--   * JSON payloads are jsonb
-- =============================================================================

CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE EXTENSION IF NOT EXISTS "pg_trgm";


-- organizations
CREATE TABLE IF NOT EXISTS "organizations" (
  "id" TEXT PRIMARY KEY,
  "name" TEXT NOT NULL,
  "slug" TEXT NOT NULL,
  "created_at" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX "ix_organizations_slug" ON "organizations" ("slug");

-- hostels
CREATE TABLE IF NOT EXISTS "hostels" (
  "id" TEXT PRIMARY KEY,
  "organization_id" TEXT NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE,
  "name" TEXT NOT NULL,
  "code" TEXT NOT NULL,
  "city" TEXT,
  "timezone" TEXT DEFAULT 'Asia/Kolkata',
  "bottle_target" INTEGER DEFAULT 4,
  "refill_deadline_hour" INTEGER DEFAULT 21,
  "settings" JSONB DEFAULT '{}',
  "created_at" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX "ix_hostels_organization_id" ON "hostels" ("organization_id");
CREATE INDEX "ix_hostels_code" ON "hostels" ("code");

-- users
CREATE TABLE IF NOT EXISTS "users" (
  "id" TEXT PRIMARY KEY,
  "email" TEXT NOT NULL,
  "password_hash" TEXT,
  "full_name" TEXT NOT NULL,
  "display_name" TEXT,
  "phone" TEXT,
  "avatar_url" TEXT,
  "role" TEXT DEFAULT 'student',
  "hostel_id" TEXT REFERENCES "hostels"("id") ON DELETE CASCADE,
  "email_verified" BOOLEAN DEFAULT FALSE,
  "onboarding_step" INTEGER DEFAULT 0,
  "onboarded" BOOLEAN DEFAULT FALSE,
  "theme" TEXT DEFAULT 'system',
  "timezone" TEXT DEFAULT 'Asia/Kolkata',
  "notify_refills" BOOLEAN DEFAULT TRUE,
  "notify_rotation" BOOLEAN DEFAULT TRUE,
  "notify_reviews" BOOLEAN DEFAULT TRUE,
  "notify_weekly" BOOLEAN DEFAULT FALSE,
  "privacy_show_contributions" BOOLEAN DEFAULT TRUE,
  "privacy_show_activity" BOOLEAN DEFAULT TRUE,
  "privacy_show_name" BOOLEAN DEFAULT TRUE,
  "created_at" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  "last_seen_at" TIMESTAMPTZ
);
CREATE INDEX "ix_users_email" ON "users" ("email");
CREATE INDEX "ix_users_hostel_id" ON "users" ("hostel_id");

-- rooms
CREATE TABLE IF NOT EXISTS "rooms" (
  "id" TEXT PRIMARY KEY,
  "hostel_id" TEXT NOT NULL REFERENCES "hostels"("id") ON DELETE CASCADE,
  "number" TEXT NOT NULL,
  "floor" TEXT,
  "bottle_target" INTEGER DEFAULT 4,
  "refill_deadline_hour" INTEGER DEFAULT 21,
  "invite_code" TEXT NOT NULL,
  "active" BOOLEAN DEFAULT TRUE,
  "created_at" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX "ix_rooms_hostel_id" ON "rooms" ("hostel_id");
CREATE INDEX "ix_rooms_invite_code" ON "rooms" ("invite_code");
CREATE INDEX "ix_rooms_hostel_id_number" ON "rooms" ("hostel_id", "number");

-- room_members
CREATE TABLE IF NOT EXISTS "room_members" (
  "id" TEXT PRIMARY KEY,
  "room_id" TEXT NOT NULL REFERENCES "rooms"("id") ON DELETE CASCADE,
  "user_id" TEXT NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,
  "hostel_id" TEXT NOT NULL REFERENCES "hostels"("id") ON DELETE CASCADE,
  "role_in_room" TEXT DEFAULT 'member',
  "joined_at" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX "ix_room_members_room_id" ON "room_members" ("room_id");
CREATE INDEX "ix_room_members_user_id" ON "room_members" ("user_id");
CREATE INDEX "ix_room_members_hostel_id" ON "room_members" ("hostel_id");

-- coolers
CREATE TABLE IF NOT EXISTS "coolers" (
